let keyCounter = 0;
function nextKey(): string {
  keyCounter += 1;
  return `k${keyCounter}`;
}

function paragraphBlock(text: string, style: string = "normal") {
  return {
    _type: "block",
    _key: nextKey(),
    style,
    markDefs: [],
    children: [
      {
        _type: "span",
        _key: nextKey(),
        text,
        marks: [],
      },
    ],
  };
}

function buildBody() {
  const blocks: unknown[] = [];
  for (const section of SECTIONS) {
    if (section.heading) {
      const style = section.level === 3 ? "h3" : "h2";
      blocks.push(paragraphBlock(section.heading, style));
    }
    for (const p of section.paragraphs) {
      blocks.push(paragraphBlock(p, "normal"));
    }
  }
  return blocks;
}

async function main() {
  console.log("Building post body…");
  const body = buildBody();
  console.log(`Body blocks: ${body.length}`);

  const existing: { _id: string } | null = await client.fetch(
    `*[_type == "post" && slug.current == $slug][0] { _id }`,
    { slug: SLUG }
  );

  const postDoc = {
    _type: "post",
    title: TITLE,
    slug: { _type: "slug", current: SLUG },
    publishedAt: "2026-06-12T12:00:00.000Z",
    author: { _type: "reference", _ref: "author-jude" },
    category: { _type: "reference", _ref: "cat-theology" },
    excerpt: EXCERPT,
    body,
  };

  if (existing) {
    await client.patch(existing._id).set(postDoc).commit();
    console.log(`✅ Updated existing post: ${TITLE}`);
  } else {
    await client.create(postDoc);
    console.log(`✅ Created new post: ${TITLE}`);
  }

  console.log(`\nDone. URL will be: /blog/${SLUG}`);
  console.log(`Allow ~5 minutes for the live site cache to refresh.`);
}

main().catch((err) => {
  console.error("Fatal error:", err);
  process.exit(1);
});
